// 6️⃣ Rotina principal (OnTick)
// ----------------------------------------------------------------
int OnTick()
{
   // Atualiza preços
   currentPrice = SymbolInfoDouble(_Symbol, SYMBOL_ASK);
   lastClose    = iClose(_Symbol, _Period, 0);

   // Só agir quando abriu nova vela (evita múltiplas entradas na mesma vela)
   static datetime lastTime = 0;
   datetime now = iTime(_Symbol, _Period, 0);
   if(now == lastTime) return; // mesma vela
   lastTime = now;

   // -------------------------------------------------------
   // 1️⃣ Determina swing high / low (últimas N barras)
   // -------------------------------------------------------
   double swingHigh = GetHighestInRange(0, (int)MinSwingBars);
   double swingLow  = GetLowestInRange(0, (int)MinSwingBars);

   // -------------------------------------------------------
   // 2️⃣ Fibonacci retracement
   // -------------------------------------------------------
   double level38, level50, level61_8;
   bool fibOk = false;
   if(EnableFibCheck)
      fibOk = CheckFibonacciRetracement(currentPrice, swingHigh, swingLow,
                                        level38, level50, level61_8);

   // -------------------------------------------------------
   // 3️⃣ Verifica se o preço está “perto” de um nível Fibonacci
   // -------------------------------------------------------
   bool nearLevel = false;
   if(fibOk)
   {
      nearLevel = (MathAbs(currentPrice - level38)   <= 0.00005) ||
                  (MathAbs(currentPrice - level50)   <= 0.00005) ||
                  (MathAbs(currentPrice - level61_8) <= 0.00005);
   }

   // -------------------------------------------------------
   // 4️⃣ Tentar abrir operação (apenas se ainda não houver posição aberta)
   // -------------------------------------------------------
   if(PositionSelect(_Symbol) == false) // sem posição
   {
      if(nearLevel)
      {
         // Escolhe a direção correta (baseado no setup)
         // (A lógica de direção já foi inserida em TryEnterTrade)
         // Aqui chamamos a função que já contém a lógica de entrada.
         // Para simplificar, passamos o preço atual como referência.
         TryEnterTrade(currentPrice, level61_8); // nível escolhido
      }
   }

   // -------------------------------------------------------
   // 5️⃣ Gerenciar trailing stop e saída
   // -------------------------------------------------------
   ManagePositions();

   return(0);
}
